<?php include 'header.php';if(isset($_GET['approve'])){$pdo->prepare("UPDATE donations SET payment_status='Approved' WHERE id=?")->execute([(int)$_GET['approve']]);header('Location:donations.php');exit;}$rows=$pdo->query('SELECT * FROM donations ORDER BY id DESC')->fetchAll(PDO::FETCH_ASSOC);?><h1>Donation Management</h1><div class="panel"><table><tr><th>দাতা</th><th>ফোন</th><th>Amount</th><th>Method</th><th>TrxID</th><th>Status</th><th>Action</th></tr><?php foreach($rows as $r):?><tr><td><?=htmlspecialchars($r['donor_name'])?></td><td><?=htmlspecialchars($r['phone'])?></td><td>৳ <?=number_format((float)$r['amount'],2)?></td><td><?=htmlspecialchars($r['method'])?></td><td><?=htmlspecialchars($r['transaction_id'])?></td><td><span class="badge"><?=htmlspecialchars($r['payment_status'])?></span></td><td><?php if($r['payment_status']!=='Approved'):?><a href="?approve=<?=$r['id']?>">Approve</a><?php endif;?></td></tr><?php endforeach;?></table></div><?php include 'footer.php';?>